    const isBestLap = this.bestLap === null || time < this.bestLap;
    if (isBestLap) this.bestLap = time;
    this.lapTime = 0;
    const info = { lap: this.lap, totalLaps: this.totalLaps, time, isBestLap, raceTime: this.raceTime };
    this._emit('onLap', info);
